def matches_log_query(record: LogRecord, query: str) -> bool:
    """Every whitespace-separated term occurs in the body or in an attribute value."""
    haystack = record.body + " " + json.dumps(dict(record.attributes), default=str)
    return all(term in haystack for term in query.split())


def _search(
    records: list[LogRecord],
    query: str,
    *,
    start: datetime | None,
    end: datetime | None,
    limit: int,
    order: SearchOrder,
    cursor: str | None,
) -> LogSearchResult:
    found = [
        r
        for r in records
        if matches_log_query(r, query)
        and (start is None or r.timestamp >= start)
        and (end is None or r.timestamp <= end)
    ]
    found.sort(key=lambda r: r.timestamp, reverse=order == "desc")
    offset = int(cursor) if cursor else 0
    page = found[offset : offset + limit]
    next_offset = offset + len(page)
    return LogSearchResult(
        records=page,
        next_cursor=str(next_offset) if next_offset < len(found) else None,
        total=len(found),
    )


